@extends('layouts.admin') @section('title',$article->exists?'Chỉnh sửa bài viết':'Viết câu chuyện mới') @section('content')<form class="editor" method="post" action="{{ $article->exists?route('articles.update',$article):route('articles.store') }}">@csrf @if($article->exists)@method('put')@endif<section class="panel fields"><label>Tiêu đề<input name="title" value="{{ old('title',$article->title) }}" required></label><label>Mô tả ngắn<textarea name="excerpt" required>{{ old('excerpt',$article->excerpt) }}</textarea></label><label>Nội dung bài<textarea class="body" name="body" required>{{ old('body',$article->body) }}</textarea></label></section><aside class="panel settings"><label>Chuyên mục<select name="category">@foreach(['Công nghệ','Flycam','Camera','Sáng tạo'] as $category)<option @selected(old('category',$article->category)===$category)>{{ $category }}</option>@endforeach</select></label><label>Ảnh bìa Cloudflare URL<input type="url" name="hero_image" value="{{ old('hero_image',$article->hero_image) }}" required></label><label>Trạng thái<select name="status">@foreach(['draft','review','published','archived'] as $status)<option @selected(old('status',$article->status)===$status)>{{ $status }}</option>@endforeach</select></label><label>Ngày xuất bản<input type="datetime-local" name="published_at" value="{{ old('published_at',$article->published_at?->format('Y-m-d\TH:i')) }}"></label><label class="check"><input type="checkbox" name="featured" value="1" @checked(old('featured',$article->featured))> Bài nổi bật</label><button class="button">Lưu bài viết</button>@if($errors->any())<div class="errors">{{ implode(' • ',$errors->all()) }}</div>@endif</aside></form>@endsection
